997	      var eps = isMobile() ? 0.02 : 0.008;
998	      for (var i = 0; i < playheads.length; i++) {
999	        var V = playheads[i];
1000	        if (!V.ready) continue;
1001	        // Never queue a seek while the decoder is still resolving the last one.
1002	        // On a phone a fast flick otherwise piles seeks up and freezes the clip.
1003	        // But a seek that never completes would freeze the clip for the life of
1004	        // the page through this very guard, so a seek stuck past 700ms is
1005	        // re-issued rather than waited on forever.
1006	        if (V.el.seeking) {
1007	          var nw = performance.now();
1008	          if (!V.stuckAt) V.stuckAt = nw;
1009	          else if (nw - V.stuckAt > 700) {
1010	            V.stuckAt = nw;
1011	            try { V.el.currentTime = V.el.currentTime + 0.001; } catch (e) {}
1012	          }
1013	          continue;
1014	        }
1015	        V.stuckAt = 0;
1016	        // An offscreen clip that has already arrived stops costing anything.
1017	        if (!V.live && Math.abs(V.cur - V.target) < 0.002) continue;
1018	        V.cur += (V.target - V.cur) * (reduce ? 1 : V.lerp);
1019	        var dur = V.el.duration || 1;
1020	        var t = clamp(V.cur, 0, 0.999) * dur;
1021	        if (Math.abs(V.el.currentTime - t) > eps) { try { V.el.currentTime = t; } catch (e) {} }
1022	      }
1023	      requestAnimationFrame(tick);
1024	    }
1025	
1026	    // iOS will not paint a muted video that has never been handed a user
1027	    // gesture, so a clip can be loaded, seeked and still show nothing.
1028	    //
1029	    // This used to fire once, on the first touch, across every playhead. That
1030	    // loses a race it cannot win. The first act's clip is still being fetched
1031	    // when the reader's first touch arrives (they touch the screen in order to
1032	    // scroll, and the clip is megabytes) so play() is called on a video with
1033	    // no source, does nothing, and the one shot is spent. Every later act loads
1034	    // long after that touch, with user activation already granted, and works
1035	    // without ever needing this. That is the exact shape of the bug: the hero
1036	    // frozen, everything below it fine.
1037	    //
1038	    // So: keep listening, prime each clip once it actually has a source, and
1039	    // stop only when they are all done. And force a seek afterwards, because a
1040	    // primed decoder still shows the stale frame until something asks it for a
1041	    // different time, and the deadband in tick() will not ask if the playhead is
1042	    // already where it should be.
1043	    var primedCount = 0;
1044	    function primeClip(V) {
1045	      // priming guards the retry: play() is a promise, and calling it again
1046	      // while the last one is unsettled produces "interrupted by pause" and can
1047	      // leave the element playing.
1048	      if (V.primed || V.priming || !V.el.src) return;
1049	      V.priming = true;
1050	      var done = function () {
1051	        V.priming = false;
1052	        if (!V.primed) { V.primed = true; primedCount++; }
1053	        try { V.el.pause(); } catch (e) {}
1054	        // repaint: nudge past the deadband so the next tick writes for real
1055	        try {
1056	          var dur = V.el.duration || 1;
1057	          V.cur = clamp(V.cur, 0, 0.999);
1058	          V.el.currentTime = clamp(V.cur * dur + 0.05, 0, dur * 0.999);
1059	        } catch (e) {}
1060	      };
1061	      var fail = function () { V.priming = false; };
1062	      // A play() promise is allowed to stay pending forever (iOS does this to a
1063	      // video it has decided not to start). If that happened here, `priming`
1064	      // would jam and no gesture could ever retry, so the flag is released on a
1065	      // timer as well. A late resolution after the release still lands in
1066	      // done(), which is idempotent.
1067	      setTimeout(function () { if (V.priming) fail(); }, 2000);
1068	      var pr;
1069	      try { pr = V.el.play(); } catch (e) { fail(); return; }
1070	      if (pr && pr.then) pr.then(done, fail);
1071	      else done();
1072	    }
1073	    function prime() {
1074	      for (var i = 0; i < playheads.length; i++) primeClip(playheads[i]);
1075	      if (playheads.length && primedCount >= playheads.length) {
1076	        removeEventListener('touchstart', prime);
1077	        removeEventListener('touchend', prime);
1078	        removeEventListener('pointerdown', prime);
1079	        removeEventListener('click', prime);
1080	        removeEventListener('scroll', prime);
1081	      }
1082	    }
1083	    // touchend and click are here because the HTML spec's list of activation-
1084	    // triggering events includes touchend but NOT touchstart. A restricted
1085	    // device (Low Power Mode) that rejects the touchstart prime for lacking
1086	    // activation gets a second, valid chance the moment the finger lifts.
1087	    addEventListener('touchstart', prime, { passive: true });
1088	    addEventListener('touchend', prime, { passive: true });
1089	    addEventListener('pointerdown', prime, { passive: true });
1090	    addEventListener('click', prime, { passive: true });
1091	    addEventListener('scroll', prime, { passive: true });
1092	
1093	    // ---- pointer devices --------------------------------------------------
1094	    var tilts = [], magnets = [], spots = [];
1095	    function initPointer() {
1096	      if (reduce || !fineMQ.matches) return;
1097	      Array.prototype.forEach.call(root.querySelectorAll('[data-sc-tilt]'), function (el) {
1098	        tilts.push({ el: el, max: parseFloat(el.getAttribute('data-sc-tilt')) || 6, x: 0, ty: 0, tx: 0, y: 0 });
1099	      });
1100	      Array.prototype.forEach.call(root.querySelectorAll('[data-sc-magnet]'), function (el) {
1101	        magnets.push({ el: el, k: parseFloat(el.getAttribute('data-sc-magnet')) || 0.3, x: 0, y: 0, tx: 0, ty: 0 });
1102	      });
1103	      Array.prototype.forEach.call(root.querySelectorAll('[data-sc-spotlight]'), function (el) {
1104	        spots.push(el);
1105	      });
1106	      if (!tilts.length && !magnets.length && !spots.length) return;
1107	
1108	      addEventListener('pointermove', function (e) {
1109	        if (e.pointerType !== 'mouse') return;
1110	        for (var i = 0; i < tilts.length; i++) {
1111	          var T = tilts[i], r = T.el.getBoundingClientRect();
1112	          if (r.bottom < -200 || r.top > vh + 200) { T.tx = 0; T.ty = 0; continue; }
1113	          var nx = (e.clientX - (r.left + r.width / 2)) / (r.width / 2);
1114	          var ny = (e.clientY - (r.top + r.height / 2)) / (r.height / 2);
1115	          var inside = Math.abs(nx) < 1.6 && Math.abs(ny) < 1.6;
1116	          T.tx = inside ? clamp(ny, -1, 1) * -T.max : 0;
1117	          T.ty = inside ? clamp(nx, -1, 1) * T.max : 0;
1118	        }
1119	        for (var m = 0; m < magnets.length; m++) {
1120	          var M = magnets[m], mr = M.el.getBoundingClientRect();
1121	          var dx = e.clientX - (mr.left + mr.width / 2);
1122	          var dy = e.clientY - (mr.top + mr.height / 2);
1123	          var near = Math.abs(dx) < mr.width && Math.abs(dy) < mr.height * 2.5;
1124	          M.tx = near ? dx * M.k : 0;
1125	          M.ty = near ? dy * M.k : 0;
1126	        }
1127	        for (var s = 0; s < spots.length; s++) {
1128	          var sr = spots[s].getBoundingClientRect();
1129	          spots[s].style.setProperty('--sc-mx', clamp01((e.clientX - sr.left) / sr.width).toFixed(3));
1130	          spots[s].style.setProperty('--sc-my', clamp01((e.clientY - sr.top) / sr.height).toFixed(3));
1131	        }
1132	      }, { passive: true });
1133	
1134	      (function pointerTick() {
1135	        // Interpolate toward the target rather than tracking the pointer
1136	        // directly. Direct tracking reads as artificial because it carries no
1137	        // momentum; the lerp gives it weight.
1138	        for (var i = 0; i < tilts.length; i++) {
1139	          var T = tilts[i];
1140	          T.x += (T.tx - T.x) * 0.09; T.y += (T.ty - T.y) * 0.09;
1141	          if (Math.abs(T.x) > 0.001 || Math.abs(T.y) > 0.001) {
1142	            T.el.style.transform = 'perspective(1100px) rotateX(' + T.x.toFixed(3) + 'deg) rotateY(' + T.y.toFixed(3) + 'deg)';
1143	          }
1144	        }
1145	        for (var m = 0; m < magnets.length; m++) {
1146	          var M = magnets[m];
1147	          M.x += (M.tx - M.x) * 0.12; M.y += (M.ty - M.y) * 0.12;
1148	          M.el.style.transform = 'translate3d(' + M.x.toFixed(2) + 'px,' + M.y.toFixed(2) + 'px,0)';
1149	        }
1150	        requestAnimationFrame(pointerTick);
1151	      })();
1152	    }
1153	
1154	    // ---- wiring -----------------------------------------------------------
1155	    var ticking = false;
1156	    addEventListener('scroll', function () {
1157	      if (!ticking) { ticking = true; requestAnimationFrame(function () { read(); ticking = false; }); }
1158	    }, { passive: true });
1159	
1160	    // Keyboard focus on a pinned or panning act. The browser's own
1161	    // scroll-into-view parks the focused element barely on screen, which is
1162	    // exactly the scroll position at which its cue has not opened yet, so focus
1163	    // lands on a control nobody can see and every automated opacity check still
1164	    // passes. Centring the act instead is a position where the cue is lit by
1165	    // definition. behavior:'instant' on purpose: scrollcraft.css sets
1166	    // scroll-behavior:smooth, so the default animates the jump and focus sits
1167	    // off screen for the whole of a multi-screen glide.
1168	    addEventListener('focusin', function (e) {
1169	      var el = e.target;
1170	      if (!el || !el.closest) return;
1171	      var act = el.closest('[data-sc-act]');
1172	      if (!act || !root.contains(act)) return;
1173	      var cue = el.closest('[data-sc-cue]');
1174	      if (!cue) return;
1175	      if (parseFloat(getComputedStyle(cue).opacity || '1') > 0.85) return;
1176	      el.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'instant' });
1177	    });
1178	
1179	    var lastW = innerWidth;
1180	    addEventListener('resize', function () {
1181	      // Ignore URL-bar-only height changes on phones. Relaying out on those
1182	      // makes the page jump under the reader's thumb for no reason.
1183	      if (innerWidth === lastW && isMobile()) { vh = innerHeight; return; }
1184	      lastW = innerWidth;
1185	      layout();
1186	    }, { passive: true });
1187	
1188	    if (document.fonts && document.fonts.ready) {
1189	      // Line splitting measures line boxes, so it has to wait for the real face.
1190	      document.fonts.ready.then(function () {
1191	        acts.forEach(function (a) { a.cues.forEach(function (q) { if (q.kinetic && q.units) { q.el.__scSplit = null; q.units = null; } }); });
1192	        layout();
1193	      });
1194	    }
1195	
1196	    layout();
1197	    initPointer();
1198	    requestAnimationFrame(tick);
1199	    document.documentElement.classList.add('sc-ready');
1200	
1201	    var api = { layout: layout, read: read, acts: acts, worlds: worlds, clips: playheads, lerp: LERP };
1202	    global.ScrollCraft.instances.push(api);
1203	    return api;
1204	  }
1205	
1206	  // The instance list is not an API for the page. It is how the verification
1207	  // harness reads the real playhead records: a screenshot taken mid-lerp is a
1208	  // frame the page never actually holds, so the harness has to be able to ask
1209	  // whether the playhead has arrived rather than guess with a timeout.
1210	  global.ScrollCraft = { mount: mount, reduce: reduce, instances: [] };
1211	})(window);
