   300vh inline height. Left in place, that height survives .rm's CSS
   override on .stage alone and leaves a dead, empty scroll track — the
   exact failure F-001 named. */
var heroActEl = document.getElementById('heroAct');
if (reduce && heroActEl){
  heroActEl.removeAttribute('data-sc-act');
